source='''from collections import Counter


def transform(grid):
    height, width = len(grid), len(grid[0])
    observed = [None] * width
    for col in range(width):
        values = [grid[row][col] for row in range(col + 1, height) if grid[row][col] != 0]
        if values:
            observed[col] = Counter(values).most_common(1)[0][0]

    period = width
    for candidate in range(1, width + 1):
        if all(
            observed[col] is None
            or (observed[col % candidate] is not None and observed[col] == observed[col % candidate])
            for col in range(width)
        ):
            period = candidate
            break

    base = []
    for col in range(width):
        if observed[col] is not None:
            base.append(observed[col])
        else:
            same_phase = [
                observed[index]
                for index in range(width)
                if observed[index] is not None and index % period == col % period
            ]
            base.append(Counter(same_phase).most_common(1)[0][0])

    return [
        [base[(col - 1) % period] if col >= row else base[col] for col in range(width)]
        for row in range(height)
    ]
